{
  "type": "function",
  "function": {
    "name": "schedule_freight_pickup",
    "description": "Schedules a freight pickup using the supplied UTC pickup time, declared currency, weight, and depot coordinates. Use it when a freight pickup needs to be scheduled. The coordinate value must be a comma-separated latitude and longitude with no spaces; the note may be null when no note is provided. This tool schedules pickups and does not specify carrier selection or freight pricing.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "pickup_iso_utc": {
          "type": "string",
          "format": "date-time",
          "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]+)?Z$",
          "description": "UTC ISO 8601 timestamp ending in Z, e.g. 2026-04-18T14:30:00Z."
        },
        "declared_currency": {
          "type": "string",
          "pattern": "^[A-Z]{3}$",
          "description": "Three-letter uppercase ISO 4217 currency code, e.g. USD."
        },
        "weight_kg": {
          "type": "number",
          "description": "Freight weight in kilograms."
        },
        "depot_coordinates": {
          "type": "string",
          "pattern": "^-?[0-9]+(\\.[0-9]+)?,-?[0-9]+(\\.[0-9]+)?$",
          "description": "Latitude and longitude as lat,lon with no spaces, e.g. 37.7749,-122.4194."
        },
        "carrier_note": {
          "type": [
            "string",
            "null"
          ],
          "description": "Optional note for the carrier, or null if no note is provided."
        }
      },
      "required": [
        "pickup_iso_utc",
        "declared_currency",
        "weight_kg",
        "depot_coordinates",
        "carrier_note"
      ],
      "additionalProperties": false
    }
  }
}

