{
  "type": "function",
  "function": {
    "name": "schedule_freight_pickup",
    "description": "Schedule a freight pickup. Provide the pickup time in UTC, an ISO 4217 currency code, the shipment weight in kilograms, and depot coordinates in the specified format.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
