{
  "type": "function",
  "function": {
    "name": "issue_prorated_credit",
    "description": "Issue a prorated billing credit. Before calling, calculate both derived values exactly from the supplied inputs. Dates are ISO 8601 calendar dates. Treat the billing cycle as [billing_start, billing_end): total_days is the number of calendar days from billing_start up to, but not including, billing_end; unused_days is the number of days from cancel_date up to, but not including, billing_end, clamped to [0, total_days]. The cancellation date itself is not credited. Calculate prorated_gross_cents = round-half-up(plan_price_cents * unused_days / total_days), then net_credit_cents = max(0, prorated_gross_cents - flat_fee_cents). The flat fee is deducted once, after prorating. Do not call if dates are invalid, billing_end is not after billing_start, or either amount is negative. Submit the original inputs and your calculated unused_days and net_credit_cents; do not estimate or omit the calculation.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "billing_start": {
          "type": "string",
          "format": "date",
          "description": "Inclusive first date of the billing cycle (YYYY-MM-DD)."
        },
        "billing_end": {
          "type": "string",
          "format": "date",
          "description": "Exclusive end date of the billing cycle (YYYY-MM-DD)."
        },
        "cancel_date": {
          "type": "string",
          "format": "date",
          "description": "Effective cancellation date (YYYY-MM-DD); this date is not credited."
        },
        "plan_price_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Full-cycle plan price in integer cents."
        },
        "flat_fee_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "One-time fee in integer cents, deducted after prorating."
        },
        "unused_days": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated as clamp(days from cancel_date to billing_end, 0, total cycle days)."
        },
        "net_credit_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated prorated credit in integer cents, using round-half-up before subtracting the flat fee, floored at zero."
        }
      },
      "required": [
        "billing_start",
        "billing_end",
        "cancel_date",
        "plan_price_cents",
        "flat_fee_cents",
        "unused_days",
        "net_credit_cents"
      ],
      "additionalProperties": false
    }
  }
}
