Design a strict JSON tool definition in OpenAI Chat Completions format (valid JSON object) for `issue_prorated_credit` specifically tuned for a fast non-reasoning model (with zero internal thinking tokens) that must calculate the exact prorated net credit in integer cents and unused billing days remaining from billing cycle dates (`billing_start`, `billing_end`, `cancel_date`), plan price, and flat fee before submitting the arguments.

### Task-Specific Rubric Criteria
- Places an upfront concise rationale field first while specifying explicit date conventions, rounding/proration formula, and bounds on sibling parameters
- Downstream achieves exact multi-step arithmetic at reasoning_effort='none' without fake/empty dates

### Candidate A
{
  "type": "function",
  "function": {
    "name": "issue_prorated_credit",
    "description": "Calculates and issues a prorated net credit in integer cents for a canceled subscription. Use this tool when the credit must be calculated from a billing cycle's dates, plan price, and flat fee before submission. Do NOT use it for general ledger lookups or discretionary billing adjustments; use the relevant billing lookup or adjustment tool instead. The billing interval is half-open: billing_start is included and billing_end is excluded; cancel_date must fall within that interval.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "rationale": {
          "type": "string",
          "description": "Concise supporting summary of the date counts and arithmetic; do not provide step-by-step hidden reasoning."
        },
        "billing_start": {
          "type": "string",
          "format": "date",
          "description": "Inclusive billing-cycle start date in YYYY-MM-DD format."
        },
        "billing_end": {
          "type": "string",
          "format": "date",
          "description": "Exclusive billing-cycle end date in YYYY-MM-DD format; must be after billing_start."
        },
        "cancel_date": {
          "type": "string",
          "format": "date",
          "description": "Cancellation date in YYYY-MM-DD format, within [billing_start, billing_end). Unused days are the calendar-day count from cancel_date to billing_end."
        },
        "plan_price_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Total plan price for this billing cycle, in integer cents (>= 0)."
        },
        "flat_fee_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Non-prorated flat fee deducted from the gross credit, in integer cents (>= 0)."
        },
        "unused_billing_days": {
          "type": "integer",
          "minimum": 0,
          "description": "Exact calendar days in [cancel_date, billing_end); calculate as the date difference in days."
        },
        "billing_cycle_days": {
          "type": "integer",
          "minimum": 1,
          "description": "Exact calendar days in [billing_start, billing_end); calculate as the date difference in days."
        },
        "net_credit_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Exact net credit in integer cents: max(0, floor(plan_price_cents * unused_billing_days / billing_cycle_days) - flat_fee_cents). Use integer arithmetic and round down."
        }
      },
      "required": [
        "rationale",
        "billing_start",
        "billing_end",
        "cancel_date",
        "plan_price_cents",
        "flat_fee_cents",
        "unused_billing_days",
        "billing_cycle_days",
        "net_credit_cents"
      ],
      "additionalProperties": false
    }
  }
}

